import math
def priority(task, state, a=1.0, b=0.5, m=1.0, k=0.5, c=1.0):
    slack = task.due - state.now - task.estimated_runtime
    mean = max(state.mean_est, 1e-6)
    wait = state.now - task.release
    tier = m if task.tenant == 'premium' else 1.0
    if slack < 0:
        return tier * (task.weight / max(task.estimated_runtime, 1e-6) + a * wait / mean)
    else:
        atc = task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / max(k * mean, 1e-6))
        return tier * (-c * slack / mean + b * atc)

