    elif task.task_type == 'variant_calling':
        beta = b_variant
    else:
        beta = b_sv
    eff_est = est * (1.0 + beta)
    slack = max(0.0, task.due - eff_est - state.now)
    base = task.weight / est * math.exp(-slack / (max(k, 1e-6) * max(state.mean_est, 1e-6)))
    if task.tenant == 'premium' and slack <= s * max(state.mean_est, 1e-6):
        base *= m
    return base

