import math
def priority(task, state, s=1.5, k=4.0):
    slack = max(0.0, task.due - s * task.estimated_runtime - state.now)
    mean_est = max(state.mean_est, 1e-6)
    return task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * mean_est))

import math
def priority(task, state, k=4.0, k2=1.0, m=3.0):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    mean_est = max(state.mean_est, 1e-6)
    base = task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * mean_est))
    if task.tenant == 'premium':
        boost = 1.0 + (m - 1.0) * math.exp(-slack / (k2 * mean_est))
    else:
        boost = 1.0
    return base * boost

import math
def priority(task, state, k=4.0, k2=1.0, b=1.0, m=3.0, align=1.0, variant=1.0, sv=1.0):
    p = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    slack = max(0.0, task.due - p - state.now)
    base = task.weight / p * math.exp(-slack / max(k * mean_est, 1e-6))
    boost = 1.0
    if task.resource_need <= state.free + 1e-9:
        ratio = task.resource_need / max(state.free, 1e-6)
        boost += b * ratio * math.exp(-slack / max(k2 * mean_est, 1e-6))
    if task.tenant == 'premium':
        boost *= 1.0 + (m - 1.0) * math.exp(-slack / max(k2 * mean_est, 1e-6))
    if task.task_type == 'alignment':
        boost *= align
    elif task.task_type == 'variant_calling':
        boost *= variant
    else:
        boost *= sv
    return base * max(boost, 1e-6)

