    slack = task.due - p - state.now - wait_risk
    if slack < 0.0:
        urgency = 1.0 + b * (-slack) / p
        base = (task.weight / p) * (urgency ** c)
    else:
        base = (task.weight / p) * math.exp(-slack / max(k * mean, 1e-6))
    if task.task_type == 'alignment':
        base *= alpha
    elif task.task_type == 'variant_calling':
        base *= beta
    else:
        base *= gamma
    if task.tenant == 'premium':
        base *= m
    return base

