import math
def priority(task, state, k=0.5, b=1.0, m=1.0):
    est = max(task.estimated_runtime, 1e-6)
    slack = task.due - state.now - est
    mean_est = max(state.mean_est, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    if slack <= 0:
        wait = max(0.0, state.now - task.release)
        return tier * task.weight / est * (1.0 + b * wait / est) * (1.0 + (-slack) / mean_est)
    else:
        return tier * task.weight / est * math.exp(-slack / (k * mean_est))

import math
def priority(task, state, k=0.5, m=1.0, r=0.2):
    est = max(task.estimated_runtime, 1e-6)
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    mean_est = max(state.mean_est, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    fit = 1.0
    if task.resource_need <= state.free:
        fit = 1.0 + r * (state.free - task.resource_need) / max(state.capacity, 1e-6)
    else:
        fit = 1.0 / (1.0 + r * (task.resource_need - state.free) / max(state.capacity, 1e-6))
    return tier * fit * task.weight / est * math.exp(-slack / (k * mean_est))

import math
def priority(task, state, k=0.5, b=0.1, m=1.0, q=0.0, w_align=1.0, w_var=1.0, w_sv=1.0, d=0.0):
    est = max(task.estimated_runtime, 1e-6)
    now = state.now
    slack = max(0.0, task.due - now - est)
    mean_est = max(state.mean_est, 1e-6)
    wait = max(0.0, now - task.release)
    if task.task_type == 'alignment':
        tw = w_align
    elif task.task_type == 'variant_calling':
        tw = w_var
    else:
        tw = w_sv
    tier = m if task.tenant == 'premium' else 1.0
    premium = 1.0
    if task.tenant == 'premium':
        premium = 1.0 + q * (wait / max(est + mean_est, 1e-6)) * (1.0 + d * state.queue_len / max(state.capacity, 1e-6))
    premium = max(premium, 1e-6)
    base = tw * tier * premium * task.weight / est
    return base * math.exp(-slack / max(k * mean_est, 1e-6)) * (1.0 + b * wait / est)

