import math
def priority(task, state, k=0.5, alpha=0.8, beta=0.5, gamma=0.5, m_align=1.0, m_var=1.0, m_sv=1.0, p_prem=1.0, p_std=1.0):
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    slack = max(0.0, task.due - est - state.now)
    core_pressure = max(0.0, min(1.0, 1.0 - state.free / max(state.capacity, 1e-6)))
    congestion = state.queue_work / max(state.capacity * mean_est, 1e-6)
    k_eff = k / (1.0 + beta * congestion + gamma * core_pressure)
    if task.task_type == 'alignment':
        type_mult = m_align
    elif task.task_type == 'variant_calling':
        type_mult = m_var
    else:
        type_mult = m_sv
    if task.tenant == 'premium':
        tenant_mult = p_prem
    else:
        tenant_mult = p_std
    core_factor = 1.0 / max(task.resource_need, 1e-6) ** (alpha * core_pressure)
    return type_mult * tenant_mult * task.weight / est * math.exp(-slack / max(k_eff * mean_est, 1e-6)) * core_factor

